files.content:
:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --accent: #e94560;
  --seat-free: #0f3460;
  --seat-taken: #2b2b3b;
  --text: #f1f1f1;
  --text-muted: #a0a0b0;
  --focus: #ffd166;
  --radius: 8px;
  --gap: 8px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.card {
  background: var(--card);
  border-radius: 16px;
  padding: 24px 20px;
  max-width: 520px;
  width: 100%;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
}

header {
  text-align: center;
  margin-bottom: 20px;
}

h1 {
  font-size: 1.6rem;
  letter-spacing: 1px;
  color: var(--accent);
}

.subtitle {
  color: var(--text-muted);
  font-size: 0.95rem;
  margin-top: 4px;
}

.screen {
  text-align: center;
  font-size: 0.8rem;
  letter-spacing: 4px;
  color: var(--text-muted);
  border-bottom: 3px solid var(--accent);
  padding-bottom: 6px;
  margin-bottom: 20px;
}

.seat-grid {
  display: grid;
  grid-template-columns: repeat(8, 1fr);
  gap: var(--gap);
  margin-bottom: 24px;
}

.seat {
  aspect-ratio: 1;
  border: none;
  border-radius: var(--radius);
  background: var(--seat-free);
  color: var(--text);
  font-size: 0.75rem;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.15s, transform 0.1s;
  min-width: 0;
  padding: 2px;
}

.seat:hover:not(:disabled) {
  background: #1a4a7a;
  transform: scale(1.05);
}

.seat:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.seat:active:not(:disabled) {
  transform: scale(0.95);
}

.seat.selected {
  background: var(--accent);
  color: #fff;
}

.seat:disabled {
  background: var(--seat-taken);
  color: #555;
  cursor: not-allowed;
}

.summary {
  text-align: center;
  margin-bottom: 20px;
  border-top: 1px solid #2a2a4a;
  padding-top: 16px;
}

.selected-seats {
  font-size: 1rem;
  color: var(--text-muted);
  min-height: 1.4em;
  word-break: break-word;
}

.total-price {
  font-size: 1.3rem;
  font-weight: 700;
  color: var(--accent);
  margin-top: 6px;
}

.reset-btn {
  display: block;
  width: 100%;
  padding: 12px;
  font-size: 1rem;
  font-weight: 600;
  border: 2px solid var(--accent);
  border-radius: var(--radius);
  background: transparent;
  color: var(--accent);
  cursor: pointer;
  transition: background 0.15s, color 0.15s, transform 0.1s;
}

.reset-btn:hover {
  background: var(--accent);
  color: #fff;
}

.reset-btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.reset-btn:active {
  transform: scale(0.97);
}

@media (max-width: 400px) {
  .card {
    padding: 18px 12px;
  }
  .seat {
    font-size: 0.65rem;
  }
  .seat-grid {
    gap: 5px;
  }
  h1 {
    font-size: 1.3rem;
  }
}

(function () {
  'use strict';

  var ROWS = ['A', 'B', 'C', 'D', 'E'];
  var COLS = 8;
  var PRICE = 9;
  var TAKEN = {
    A: [3, 4],
    B: [6],
    C: [1, 2, 7],
    D: [5],
    E: [2, 3, 8]
  };

  var grid = document.getElementById('seat-grid');
  var selectedEl = document.getElementById('selected-seats');
  var totalEl = document.getElementById('total-price');
  var resetBtn = document.getElementById('reset-btn');

  var selected = {};

  function isTaken(row, col) {
    return TAKEN[row] && TAKEN[row].indexOf(col) !== -1;
  }

  function buildGrid() {
    ROWS.forEach(function (row) {
      for (var col = 1; col <= COLS; col++) {
        var btn = document.createElement('button');
        btn.type = 'button';
        btn.className = 'seat';
        btn.dataset.row = row;
        btn.dataset.col = col;
        var label = row + col;
        btn.textContent = label;
        if (isTaken(row, col)) {
          btn.disabled = true;
          btn.setAttribute('aria-label', 'Seat ' + label + ' taken');
        } else {
          btn.setAttribute('aria-label', 'Seat ' + label + ' free');
          btn.addEventListener('click', onSeatClick);
        }
        grid.appendChild(btn);
      }
    });
  }

  function onSeatClick(e) {
    var btn = e.currentTarget;
    var key = btn.dataset.row + btn.dataset.col;
    if (selected[key]) {
      delete selected[key];
      btn.classList.remove('selected');
      btn.setAttribute('aria-pressed', 'false');
      btn.setAttribute('aria-label', 'Seat ' + key + ' free');
    } else {
      selected[key] = true;
      btn.classList.add('selected');
      btn.setAttribute('aria-pressed', 'true');
      btn.setAttribute('aria-label', 'Seat ' + key + ' selected');
    }
    updateSummary();
  }

  function updateSummary() {
    var keys = Object.keys(selected).sort(function (a, b) {
      if (a[0] !== b[0]) return a[0] < b[0] ? -1 : 1;
      return parseInt(a.slice(1), 10) - parseInt(b.slice(1), 10);
    });
    if (keys.length === 0) {
      selectedEl.textContent = 'No seats selected';
    } else {
      selectedEl.textContent = keys.join(', ');
    }
    totalEl.textContent = 'Total: $' + keys.length * PRICE;
  }

  function reset() {
    selected = {};
    var seats = grid.querySelectorAll('.seat.selected');
    seats.forEach(function (btn) {
      btn.classList.remove('selected');
      btn.setAttribute('aria-pressed', 'false');
      var key = btn.dataset.row + btn.dataset.col;
      btn.setAttribute('aria-label', 'Seat ' + key + ' free');
    });
    updateSummary();
  }

  resetBtn.addEventListener('click', reset);
  buildGrid();
  updateSummary();
})();
